'use strict';
// Reverse proxy in front of the alcove app (the app itself is unmodified).
//
// The umami browser tag stays on the page, but a headless client that exits at the
// `load` event kills the beacon in flight: the tracker fires at readyState
// "interactive" and `load` follows within a few ms, which is far less than one
// round trip. This records the pageview server-side for genuine page requests so
// the visit is counted regardless of how briefly the client stays alive.
const http = require('http');

const UMAMI_HOST = process.env.UMAMI_HOST || 'umami';
const UMAMI_PORT = parseInt(process.env.UMAMI_PORT || '3000', 10);
const WEBSITE_ID = process.env.UMAMI_WEBSITE_ID || '';
const UP_HOST = process.env.UPSTREAM_HOST || 'alcove';
const UP_PORT = parseInt(process.env.UPSTREAM_PORT || '3000', 10);
const PORT = parseInt(process.env.PORT || '3002', 10);

const SKIP = /\.(js|css|png|jpg|jpeg|gif|svg|ico|woff2?|map|txt|xml|json)$/i;

function report(req) {
  if (!WEBSITE_ID) return;
  const url = req.url || '/';
  const path = url.split('?')[0];
  // Never report health checks or asset requests - only real page views.
  if (path === '/healthz' || path === '/favicon.ico' || SKIP.test(path)) return;
  const xff = String(req.headers['x-forwarded-for'] || '').split(',')[0].trim();
  const payload = {
    website: WEBSITE_ID,
    hostname: String(req.headers.host || '').split(':')[0],
    url: url,
    referrer: req.headers.referer || '',
    language: String(req.headers['accept-language'] || '').split(',')[0] || 'en-US',
    screen: '1920x1080',
    title: 'Alcove, save what matters',
  };
  if (xff) payload.ip = xff;
  if (req.headers['user-agent']) payload.userAgent = req.headers['user-agent'];
  const body = JSON.stringify({ type: 'event', payload: payload });
  const r = http.request({
    host: UMAMI_HOST, port: UMAMI_PORT, path: '/api/send', method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) },
  }, function (res) { res.resume(); });
  r.on('error', function () {});
  r.end(body);
}

http.createServer(function (req, res) {
  report(req);
  const up = http.request({ host: UP_HOST, port: UP_PORT, path: req.url, method: req.method, headers: req.headers },
    function (u) { res.writeHead(u.statusCode, u.headers); u.pipe(res); });
  up.on('error', function () { if (!res.headersSent) res.writeHead(502); res.end('bad gateway'); });
  req.pipe(up);
}).listen(PORT, function () { console.log('proxy listening on ' + PORT); });
