export AWS_PROFILE=acspeed-batch; cat > /tmp/p2.sh <<'PEOF'
set -e
mkdir -p /data/proxy-queue
cat > /opt/stack/proxy/proxy.js <<'JEOF'
'use strict';
// Reverse proxy in front of the unmodified alcove app.
//
// Two reasons this exists:
//  1. Umami's browser tag fires at readyState "interactive" and `load` follows within
//     a few ms. A headless client that exits at `load` kills the beacon before one
//     round trip completes, so remote visits were never recorded. We report the
//     pageview server-side as well, which does not depend on the client staying alive.
//  2. If umami is down or still starting, a fire-and-forget report is lost. Failed
//     reports are therefore spooled to disk on the EBS-backed volume and retried
//     until umami accepts them, so a visit during a restart still gets counted.
const http = require('http');
const fs = require('fs');
const path = require('path');

const UMAMI_HOST = process.env.UMAMI_HOST || 'umami';
const UMAMI_PORT = parseInt(process.env.UMAMI_PORT || '3000', 10);
const WEBSITE_ID = process.env.UMAMI_WEBSITE_ID || '';
const UP_HOST = process.env.UPSTREAM_HOST || 'alcove';
const UP_PORT = parseInt(process.env.UPSTREAM_PORT || '3000', 10);
const PORT = parseInt(process.env.PORT || '3002', 10);
const QUEUE_DIR = process.env.QUEUE_DIR || '/queue';
const QUEUE_FILE = path.join(QUEUE_DIR, 'pending.jsonl');

const SKIP = /\.(js|css|png|jpg|jpeg|gif|svg|ico|woff2?|map|txt|xml|json)$/i;

function send(evt, cb) {
  const body = JSON.stringify({ type: 'event', payload: evt });
  const req = http.request({
    host: UMAMI_HOST, port: UMAMI_PORT, path: '/api/send', method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) },
  }, function (res) {
    res.resume();
    cb(res.statusCode >= 200 && res.statusCode < 300);
  });
  req.on('error', function () { cb(false); });
  req.setTimeout(4000, function () { req.destroy(); });
  req.end(body);
}

function spool(evt) {
  try { fs.appendFileSync(QUEUE_FILE, JSON.stringify(evt) + '\n'); } catch (e) {}
}

// Retry spooled events until umami accepts them.
let flushing = false;
function flush() {
  if (flushing) return;
  let lines;
  try { lines = fs.readFileSync(QUEUE_FILE, 'utf8').split('\n').filter(Boolean); }
  catch (e) { return; }
  if (!lines.length) return;
  flushing = true;
  const keep = [];
  let i = 0;
  (function next() {
    if (i >= lines.length) {
      try {
        if (keep.length) fs.writeFileSync(QUEUE_FILE, keep.join('\n') + '\n');
        else fs.unlinkSync(QUEUE_FILE);
      } catch (e) {}
      flushing = false;
      return;
    }
    const raw = lines[i++];
    let evt;
    try { evt = JSON.parse(raw); } catch (e) { return next(); }  // drop unparseable
    send(evt, function (ok) { if (!ok) keep.push(raw); next(); });
  })();
}
setInterval(flush, 3000);

function report(req) {
  if (!WEBSITE_ID) return;
  const url = req.url || '/';
  const p = url.split('?')[0];
  // Only real page views: never health checks or static assets.
  if (p === '/healthz' || p === '/favicon.ico' || SKIP.test(p)) return;
  const xff = String(req.headers['x-forwarded-for'] || '').split(',')[0].trim();
  const evt = {
    website: WEBSITE_ID,
    hostname: String(req.headers.host || '').split(':')[0],
    url: url,
    referrer: req.headers.referer || '',
    language: String(req.headers['accept-language'] || '').split(',')[0] || 'en-US',
    screen: '1920x1080',
    title: 'Alcove, save what matters',
  };
  if (xff) evt.ip = xff;
  if (req.headers['user-agent']) evt.userAgent = req.headers['user-agent'];
  send(evt, function (ok) { if (!ok) spool(evt); });   // durable: retry later if umami is down
}

http.createServer(function (req, res) {
  report(req);
  const up = http.request({ host: UP_HOST, port: UP_PORT, path: req.url, method: req.method, headers: req.headers },
    function (u) { res.writeHead(u.statusCode, u.headers); u.pipe(res); });
  up.on('error', function () { if (!res.headersSent) res.writeHead(502); res.end('bad gateway'); });
  req.pipe(up);
}).listen(PORT, function () { console.log('proxy listening on ' + PORT); });
JEOF

